using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class CityMedianBlink{static CityMedianBlink(){EditorApplication.update+=Run;}static void Run(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityMedianBlink.request"))return;File.Delete("CityMedianBlink.request");try{Build();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/MedianBlink.txt",e.ToString());Debug.LogException(e);}}
static void Build(){var sc=SceneManager.GetActiveScene();var all=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).ToArray();int lights=sc.GetRootGameObjects().Sum(g=>g.GetComponentsInChildren<Light>(true).Length);var materials=all.SelectMany(r=>r.sharedMaterials).Where(m=>m&&(m.shader.name=="Gangstar City/Road Atlas Lit"||m.shader.name=="Gangstar City/Road Detail PNG Atlas")).Distinct().ToArray();if(materials.Length==0)throw new Exception("No matching city road materials found");const string backup="FinalEnvironmentRoadBackup/BeforeMedianBlink";if(!File.Exists(backup+"/Scene.unity"))EditorSceneManager.SaveScene(sc,backup+"/Scene.unity",true);foreach(var m in materials){if(!File.Exists(backup+"/"+m.name+".mat"))File.Copy(AssetDatabase.GetAssetPath(m),backup+"/"+m.name+".mat");AssetDatabase.ImportAsset(AssetDatabase.GetAssetPath(m.shader),ImportAssetOptions.ForceUpdate);if(!m.HasProperty("_CrossingDotGlow")||ShaderUtil.ShaderHasError(m.shader))throw new Exception("Crossing shader validation failed: "+m.name);m.SetFloat("_MedianLightsEnabled",1);m.SetFloat("_MedianBlinkEnabled",1);m.SetFloat("_MedianBlinkSpeed",1);m.SetFloat("_MedianLightGlow",3.0f);m.enableInstancing=true;EditorUtility.SetDirty(m);}
var read=typeof(FinalPathwayRepair).GetMethod("Read",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static);var matches=new List<Renderer>();long tris=0;foreach(var r in all){var f=r.GetComponent<MeshFilter>();if(!f||!f.sharedMesh||!r.sharedMaterials.Any(materials.Contains))continue;var data=read.Invoke(null,new object[]{f.sharedMesh});var ty=data.GetType();var uv=(Vector2[])ty.GetField("uv").GetValue(data);tris+=((int[])ty.GetField("ids").GetValue(data)).Length/3;if(uv.Any(p=>Mathf.FloorToInt(p.x/32)==0))matches.Add(r);}if(matches.Count==0)throw new Exception("No slice 0 road meshes found");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);var c=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=c.IsNight;var selected=Selection.activeGameObject?Selection.activeGameObject.GetComponent<Renderer>():null;var chosen=matches.Contains(selected)?selected:matches.Where(r=>r.bounds.size.x<65&&r.bounds.size.z<65&&r.bounds.size.y<1).OrderBy(r=>Vector3.Distance(r.bounds.center,new Vector3(100,30,-100))).FirstOrDefault()??matches.First();var b=chosen.bounds;float height=Mathf.Max(b.size.x,b.size.z)*1.25f;var cap=typeof(CityTaxiStandBuild).GetMethod("Capture",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static);try{c.Apply(true);foreach(var m in materials){m.SetFloat("_MedianBlinkEnabled",0);m.SetFloat("_MedianLightsEnabled",1);}cap.Invoke(null,new object[]{sc,b.center+Vector3.up*height+Vector3.forward*.02f,b.center,"Median-Lights-On"});foreach(var m in materials)m.SetFloat("_MedianLightsEnabled",0);cap.Invoke(null,new object[]{sc,b.center+Vector3.up*height+Vector3.forward*.02f,b.center,"Median-Lights-Off"});}finally{foreach(var m in materials){m.SetFloat("_MedianLightsEnabled",1);m.SetFloat("_MedianBlinkEnabled",1);EditorUtility.SetDirty(m);}AssetDatabase.SaveAssets();c.Apply(night);}if(lights!=sc.GetRootGameObjects().Sum(g=>g.GetComponentsInChildren<Light>(true).Length)||materials.Any(m=>ShaderUtil.ShaderHasError(m.shader)))throw new Exception("Final crossing verification failed");File.WriteAllText("FinalEnvironmentRoadReview/MedianBlink.txt","SUCCESS: "+matches.Count+" matching road renderers use existing shared materials: "+string.Join(", ",materials.Select(m=>m.name))+". Only existing orange centre-median lenses in slice 0 blink amber at 1 Hz, with short soft edges; kerbs and road markings excluded. On/off, blink enable, speed and brightness exposed in road material inspector. Uses GPU time; no per-object runtime scripts or material instances. No meshes, materials, textures, renderers, real-time lights or texture samples added. Existing source albedo used as lens mask. Brighter at night; blink also visible by day. Existing road triangles="+tris+" unchanged; lights="+lights+" unchanged. Shader errors=0. Android device FPS unmeasured.\n"+string.Join("\n",matches.Select(r=>r.name+" "+r.bounds)));}
}

